extern "C" int larger_visit_probe(const inference_cuda_dense_gemv_args *,cudaStream_t);
void cap_probe(const char *dir,int c,int n,int k,int m){
    size_t bytes=size_t(n)*k/(c==8?32:256)*(c==8?34:c==12?144:c==13?176:c==14?210:98);auto data=load(std::string(dir)+"/"+(c==8 && n!=384?"q8-":"extra-"+std::to_string(c)+"-")+std::to_string(k)+"-"+std::to_string(n)+".bin",bytes);Stream s;Buffer<uint8_t>w(bytes);Buffer<float>x(m*k),y(m*n);std::vector<float> input(m*k),out(m*n),ref;for(size_t i=0;i<input.size();i++)input[i]=float(int(i%271)-134)/99.f;
    check(cudaMemcpy(x.p,input.data(),4*input.size(),cudaMemcpyHostToDevice));check(cudaMemcpy(w.p,data.data(),bytes,cudaMemcpyHostToDevice));inference_cuda_dense_gemv_args a{w.p,x.p,y.p,m,n,k,k,n,256+c};
    for(int arm=0;arm<3;arm++){auto launch=[&]{int stage=0;if(arm==0)require(!inference_cuda_dense_gemv_launch(&a,s.id,&stage),"large reference");else if(arm==1){for(int base=0;base<m;base+=64){auto chunk=a;chunk.m=std::min(64,m-base);chunk.x=x.p+base*k;chunk.y=y.p+base*n;require(!inference_cuda_inkling_packed_visit_launch(&chunk,s.id,&stage,3),"large chunked");}}else require(!larger_visit_probe(&a,s.id),"large prefetch");};
        for(int i=0;i<3;i++)launch(); Event st,ed;check(cudaEventRecord(st.id,s.id));for(int i=0;i<12;i++)launch();check(cudaEventRecord(ed.id,s.id));check(cudaEventSynchronize(ed.id));float ms;check(cudaEventElapsedTime(&ms,st.id,ed.id));check(cudaMemcpy(out.data(),y.p,out.size()*4,cudaMemcpyDeviceToHost));if(!arm)ref=out;require(!memcmp(out.data(),ref.data(),out.size()*4),"large mismatch");double us=ms*1000./12;fprintf(stderr,"cap codec=%d n=%d k=%d m=%d arm=%d us=%.3f exact=%zu\n",c,n,k,m,arm,us,arm?out.size():0);}
}
